import csv
ids={'CHWPump01':'81cf18e6-4817-56b7-8c3a-15cf474e449f','CondPump02':'7c6fe42d-3c16-55d2-b72a-7bab085d5a60','SupplyFan_AHU01':'4693f367-6f23-5b26-868f-f17e866f28b6'}
data={k:[] for k in ids}
for r in csv.DictReader(open(VALUES_CSV)):
    if r['timeseries_id'] in ids.values():
        pass
# map id back
rev={v:k for k,v in ids.items()}
for r in csv.DictReader(open(VALUES_CSV)):
    tid=r['timeseries_id']
    if tid in rev:
        data[rev[tid]].append((r['timestamp'],float(r['value'])))
for k in ids:
    allvals=[v for _,v in data[k]]
    day=[v for t,v in data[k] if t.startswith('2018-04-24')]
    rh=max(allvals); dh=max(day)
    print(k,'record_high',rh,'day_high',dh,'ratio',dh/rh,'n',len(allvals),len(day))
